	@Test
	void joinOverUnionHasCostedAlternativeWithoutLosingOriginal() {
		Value one = VF.createLiteral(1);
		Value two = VF.createLiteral(2);
		Join original = new Join(values("x", one, one, null),
				new Union(values("x", one), values("x", two)));
		PackedQuery packed = encode(original);
		assertEquals(PackedRelOp.JOIN, packed.relOperator(packed.rootRelId()));
		assertTrue(hasRootAlternative(packed, PackedRelOp.UNION),
				"JOIN over UNION must retain its JOIN seed and add a separately costed UNION member");
		assertEveryRootAlternative(packed, model(),
				List.of("x=" + one, "x=" + one, "x=" + one, "x=" + two));
	}

