	private static void assertCostChoice(TupleExpr original, Model data, boolean preferUnion) {
		PackedQuery packed = encode(original);
		int rootGroup = packed.relGroup(packed.rootRelId());
		Set<Integer> costedRootOperators = new HashSet<>();
		int[] costedRootPhysicalJoins = new int[1];
		PackedCostModel costs = new PackedCostModel() {
			@Override
			public double estimateRows(PackedQueryView query, int relationId) {
				return 1.0d;
			}

			@Override
			public PackedCostSession openSession(PackedQueryView query) {
				return new PackedCostSession() {
					private static final int ROOT_JOIN_STATE = 1;

					@Override
					public void estimateLeaf(int relationId, PackedCostContext context, PackedCostEstimate output) {
						output.setRows(1.0d, 1.0d);
						output.setEvidenceStateId(0);
					}

					@Override
					public void appendFactor(int relationId, PackedCostContext context, PackedCostEstimate output) {
						estimateLeaf(relationId, context, output);
					}

					@Override
					public void refineOperator(int relationId, PackedCostContext context, PackedCostEstimate output) {
						if (query.relGroup(relationId) == rootGroup) {
							int operator = query.operatorTag(relationId);
							costedRootOperators.add(operator);
							if (operator == PackedRelOp.JOIN) {
								output.setEvidenceStateId(ROOT_JOIN_STATE);
							} else if (operator == PackedRelOp.UNION) {
								setLocalPrice(output, preferUnion);
							}
						}
					}

					@Override
					public void refineIntermediateJoin(PackedCostContext context, PackedCostEstimate output) {
						// JOIN gets a concrete dependent/hash implementation price after logical refinement.
						// Carry the root's logical evidence into that event rather than pricing an obsolete vector.
						if (context.hasPhysicalJoinRefinement() && output.evidenceStateId() == ROOT_JOIN_STATE) {
							costedRootPhysicalJoins[0]++;
							setLocalPrice(output, !preferUnion);
						}
					}
				};
			}
		};
		TupleExpr selected = PackedCascadesPlanner.optimize(original.clone(),
				OptimizationGoal.root(original, null), costs).selectedPlan();
		assertTrue(costedRootOperators.containsAll(Set.of(PackedRelOp.JOIN, PackedRelOp.UNION)),
				"both equivalent JOIN and UNION roots must reach physical costing");
		assertTrue(costedRootPhysicalJoins[0] > 0, "the root JOIN price must reach concrete physical candidates");
		if (preferUnion) {
			assertInstanceOf(Union.class, selected, selected::toString);
		} else {
			assertInstanceOf(Join.class, selected, selected::toString);
		}
		assertEquals(evaluate(data, original), evaluate(data, selected));
	}

	private static void setLocalPrice(PackedCostEstimate output, boolean preferred) {
		output.setLocalPhysicalCost(preferred ? 0.0d : 1_000_000.0d,
				0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d);
	}

