	@Test
	void factoringDoesNotExposeAnInputOnlyPatternTermToNewBindings() {
		StatementPattern hiddenInput = new StatementPattern(Var.of("x"),
				Var.of("_p", VF.createIRI("urn:t:p"), true, true), Var.of("y", null, false, true));
		StatementPattern common = new StatementPattern(Var.of("y"),
				Var.of("_q", VF.createIRI("urn:t:q"), true, true),
				Var.of("_accepted", VF.createIRI("urn:t:accepted"), true, true));
		BindingSetAssignment choice = values("branch", VF.createLiteral("R"));
		Union original = new Union(new Join(hiddenInput, common), new Join(common.clone(), choice));
		Model data = model();
		data.add(VF.createIRI("urn:t:a"), VF.createIRI("urn:t:p"), VF.createIRI("urn:t:v1"));
		data.add(VF.createIRI("urn:t:a"), VF.createIRI("urn:t:p"), VF.createIRI("urn:t:v2"));
		data.add(VF.createIRI("urn:t:v1"), VF.createIRI("urn:t:q"), VF.createIRI("urn:t:accepted"));
		assertEquals(3, evaluate(data, original).size());
		Join unsafeFactoring = new Join(common.clone(), new Union(hiddenInput.clone(), choice.clone()));
		assertEquals(2, evaluate(data, unsafeFactoring).size(),
				"a constant-without-value term observes incoming y without producing it");
		assertFalse(hasRootAlternative(encode(original), PackedRelOp.JOIN),
				"factoring must not supply a newly bound y to the input-only pattern term");
	}

