	@Test
	void nestedUnionProductDoesNotExpandIntoExponentialNormalForm() {
		int factors = 18;
		TupleExpr original = new Union(values("v0", VF.createLiteral(1)), values("v0", VF.createLiteral(2)));
		for (int index = 1; index < factors; index++) {
			original = new Join(original, new Union(values("v" + index, VF.createLiteral(1)),
					values("v" + index, VF.createLiteral(2))));
		}
		PlanningGraphDomains.capture(original, PlanningGraphDomain.defaultGraph());
		int originalRows = PackedQueryCodec.encode(original.clone()).relationCount();
		PackedQuery packed = encode(original);
		assertTrue(hasRootAlternative(packed, PackedRelOp.UNION));
		assertTrue(packed.relationCount() <= originalRows + 6 * (factors - 1),
				"binary distribution must be bounded by original JOIN rows, not the 2^18 expanded branches");
	}

	private static TupleExpr body(String query) {
		TupleExpr result = PackedPlanDifferentialSupport.parse(query);
		while (result instanceof QueryRoot || result instanceof Projection) {
			result = ((UnaryTupleOperator) result).getArg();
		}
		return result.clone();
	}

	private static StatementPattern pattern(String predicate, String objectName) {
		Var predicateVar = Var.of("_" + predicate, VF.createIRI("urn:t:" + predicate), true, true);
		return new StatementPattern(new Var("s"), predicateVar, new Var(objectName));
	}

	private static Model oneStatement() {
		Model result = model();
		result.add(VF.createIRI("urn:t:s"), VF.createIRI("urn:t:p"), VF.createLiteral(1));
		return result;
	}

	private static PackedQuery encode(TupleExpr expression) {
		PlanningGraphDomains.capture(expression, PlanningGraphDomain.defaultGraph());
		return PackedQueryCodec.encodeForPlanning(expression);
	}

	private static boolean hasRootAlternative(PackedQuery query, int operator) {
		int group = query.relGroup(query.rootRelId());
		for (int id = 1; id <= query.relationCount(); id++) {
			if (query.relGroup(id) == group && query.relOperator(id) == operator) {
				return true;
			}
		}
		return false;
	}

	private static void assertEveryRootAlternative(PackedQuery query, Model data, List<String> expected) {
		PackedQueryView view = new PackedQueryView(query);
		int checked = 0;
		for (int id = 1; id <= query.relationCount(); id++) {
			if (query.relGroup(id) == query.relGroup(query.rootRelId())) {
				assertEquals(expected.stream().sorted().toList(), evaluate(data, view.materializeRelation(id)),
						"alternative " + id + " changed the result bag");
				checked++;
			}
		}
		assertTrue(checked >= 2, "both the original and its costed rewrite must be evaluated");
	}

	private static BindingSetAssignment values(String name, Value... values) {
		List<BindingSet> rows = new ArrayList<>();
		for (Value value : values) {
			rows.add(value == null ? EmptyBindingSet.getInstance() : new ListBindingSet(List.of(name), value));
		}
		BindingSetAssignment assignment = new BindingSetAssignment();
		assignment.setBindingNames(Set.of(name));
		assignment.setBindingSets(List.copyOf(rows));
		return assignment;
	}
